package io.github.ningpp.compat;

/** Replacement for System.Management.Automation.PSArgumentOutOfRangeException (generated by CSharpToJava converter). */
public class PSArgumentOutOfRangeException extends IndexOutOfBoundsException {
    private int hresult;
    public PSArgumentOutOfRangeException() { super(); }
    public PSArgumentOutOfRangeException(String message) { super(message); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
